package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.*;
import com.lianxibu.site.service.articles.*;
import com.lianxibu.site.service.content.CatalogAnalysisContentBaselineService;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Actual original day/analysis INPUT, fresh native locks, no dispatch authorization or model calls yet. */
class CatalogDayAnalysisDispatchPermitTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisPreparationTest helper(){return new CatalogDayAnalysisPreparationTest(){@Override boolean mysql(){return CatalogDayAnalysisDispatchPermitTest.this.mysql();}};}
    record Built(CatalogAnalysisInputProfileTest.Built data,GenerationFlowService.Frozen input){ }
    Built fixture(String category,boolean alias){var helper=helper();var data=helper.helper().fixture(category,alias);return new Built(data,helper.service(data).prepare(data.data().outer().day,data.data().receipt().entityId()).input());}
    CatalogDayAnalysisDispatchPermitService provider(Built built){var data=built.data().data();var f=data.f();String category=f.f.category;var original=new CatalogDayAnalysisCommitPermitService(data.outer().evidence(f,Clock.fixed(data.outer().completed.plusSeconds(60),ZoneOffset.UTC)),f.graph.permits(),new JdbcSourceDayDedupClosures(f.f.source),f.f.tx,category);return new CatalogDayAnalysisDispatchPermitService(f.f.source,new CatalogAnalysisPreparedInputService(f.f.source,f.f.tx,mock(Clock.class),category),original,new CatalogEntityAnalysisHeaderService(f.f.source,f.f.tx,category),new EntityInputEvidenceService(new JdbcEntityDedup(f.f.source),new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(f.f.source))),new CatalogAnalysisContentBaselineService(f.f.source,f.f.tx,category),new CatalogPreviousAnalysisService(f.f.source,f.f.tx),new JdbcCatalogVersionJobFacts(f.f.source,category),f.f.tx,category);}
    @Test void FourCategoriesProveActualOriginalDayFullInputAndFreshLockedCurrentMembers(){for(String category:List.of("agent","skill","workflow","model")){var built=fixture(category,false);var data=built.data().data();var service=provider(built);int jobs=data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var permit=service.capture(built.input().ownerId());assertEquals(built.input().ownerId(),permit.rootId());assertEquals(built.input().inputHash(),permit.inputHash());assertTrue(data.f().write(()->service.verify(permit)));assertEquals(jobs,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,data.f().f.sends);assertFalse(permit.toString().contains("fictional"));}}
    @Test void ActualVersionTwoLocksAndRechecksCompletePreviousNativeResult(){var built=fixture("agent",true);var data=built.data().data();var service=provider(built);var permit=service.capture(built.input().ownerId());assertTrue(data.f().write(()->service.verify(permit)));assertThrows(RuntimeException.class,()->data.f().write(()->{data.f().f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE owner_job_id=? AND purpose='result'",new byte[32],CatalogPreviousAnalysisTest.Fixture.ROOT);return service.verify(permit);}));assertTrue(data.f().write(()->service.verify(permit)));assertEquals(2,data.f().f.sends);}
    @Test void CurrentGenerationOrSelectedBodyChangeCannotReuseFrozenPermission(){var built=fixture("skill",false);var data=built.data().data();var service=provider(built);var permit=service.capture(built.input().ownerId());data.f().f.jdbc.update("UPDATE analyzed_entities SET analysis_generation=analysis_generation+1");assertFalse(data.f().write(()->service.verify(permit)));data.f().f.jdbc.update("UPDATE analyzed_entities SET analysis_generation=analysis_generation-1");data.f().f.jdbc.update("UPDATE source_run_items SET evidence_hash=?",new byte[32]);assertThrows(RuntimeException.class,()->data.f().write(()->service.verify(permit)));assertEquals(0,data.f().f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,built.input().ownerId()));assertEquals(2,data.f().f.sends);}
    @Test void OrdinaryContentReviewRevisionChangeIsAConflictWithoutReplacingTheOriginalInput(){var built=fixture("model",true);var data=built.data().data();var service=provider(built);var permit=service.capture(built.input().ownerId());data.f().f.jdbc.update("UPDATE contents SET revision=revision+1");assertFalse(data.f().write(()->service.verify(permit)));assertEquals(built.input(),new CatalogAnalysisPreparedInputService(data.f().f.source,data.f().f.tx,mock(Clock.class),"model").find(data.outer().day,data.receipt().entityId()).input());assertEquals(2,data.f().f.sends);}
    @Test void OriginalDayArchiveInputPartsInitialRequestAndReceiptDamageAreRejected(){var built=fixture("workflow",false);var data=built.data().data();var service=provider(built);var permit=service.capture(built.input().ownerId());for(String sql:List.of("UPDATE jobs SET action_payload_hash=? WHERE target_type='source_day_dedup'","UPDATE jobs SET payload_hash=? WHERE owner_job_id='"+built.input().ownerId()+"' AND purpose='input'","UPDATE jobs SET action_payload_hash=? WHERE target_type='catalog_day_analysis'")){assertThrows(RuntimeException.class,()->data.f().write(()->{int changed=data.f().f.jdbc.update(sql,new byte[32]);assertTrue(changed>0);return service.verify(permit);}));}assertThrows(RuntimeException.class,()->data.f().write(()->{data.f().f.jdbc.update("UPDATE jobs SET request_json='{}' WHERE id=?",JdbcFrozenInputs.stableId("attempt",built.input().ownerId()+":1"));return service.verify(permit);}));assertTrue(data.f().write(()->service.verify(permit)));assertEquals(2,data.f().f.sends);}
    @Test void IssuerAndTransactionRolesAreClosedAndCurrentSourceChangesDoNotRebuildOriginalDay(){var built=fixture("agent",false);var data=built.data().data();var service=provider(built);var permit=service.capture(built.input().ownerId());assertThrows(RuntimeException.class,()->service.verify(permit));assertThrows(RuntimeException.class,()->data.f().write(()->service.capture(built.input().ownerId())));assertThrows(RuntimeException.class,()->data.f().write(()->provider(built).verify(permit)));assertThrows(RuntimeException.class,()->data.outer().snapshot(data.f(),()->service.verify(permit)));data.f().f.jdbc.update("UPDATE sources SET state='disabled'");var restart=service.capture(built.input().ownerId());assertTrue(data.f().write(()->service.verify(restart)));}
    @Test void NativeOriginalRequestLockIsHeldUntilCallerCommit() throws Exception{if(!mysql())return;var built=fixture("skill",false);var data=built.data().data();var service=provider(built);var permit=service.capture(built.input().ownerId());String attempt=JdbcFrozenInputs.stableId("attempt",built.input().ownerId()+":1");data.f().write(()->{assertTrue(service.verify(permit));try(var threads=Executors.newSingleThreadExecutor()){assertTrue(threads.submit(()->{try(var connection=data.f().f.source.getConnection();var statement=connection.createStatement()){statement.execute("SET SESSION innodb_lock_wait_timeout=1");try(var update=connection.prepareStatement("UPDATE jobs SET request_json=request_json WHERE id=?")){update.setString(1,attempt);update.executeUpdate();return false;}}catch(java.sql.SQLException failure){return failure.getErrorCode()==1205;}}).get(3,TimeUnit.SECONDS));}catch(Exception failure){throw new RuntimeException(failure);}return true;});assertEquals(2,data.f().f.sends);}
    @Test void MandatoryClosedConstructionDoesNoIo(){var source=mock(DataSource.class);var prepared=mock(CatalogAnalysisPreparedInputService.class);var day=mock(CatalogDayAnalysisCommitPermitService.class);var headers=mock(CatalogEntityAnalysisHeaderService.class);var members=mock(EntityInputEvidenceService.class);var content=mock(CatalogAnalysisContentBaselineService.class);var previous=mock(CatalogPreviousAnalysisService.class);var jobs=mock(JdbcCatalogVersionJobFacts.class);var manager=mock(PlatformTransactionManager.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogDayAnalysisDispatchPermitService(source,prepared,day,headers,members,content,previous,jobs,manager,category));verifyNoInteractions(source,prepared,day,headers,members,content,previous,jobs,manager);assertThrows(RuntimeException.class,()->new CatalogDayAnalysisDispatchPermitService(source,prepared,day,headers,members,content,previous,jobs,manager,"news_tech"));}
}
